_AMOUNT_RE=re.compile(r'(\d{1,3}(?:,\d{3})*(?:\.\d{1,2})|\d+(?:\.\d{1,2})|\d+,\d{2})')
HARD=['SUBTOTAL','SUB TOTAL','SUB-TOTAL','DISCOUNT','CHANGE','CASH TENDERED']
SOFT=['TAX','GST','SST']
CTX=['SUMMARY']
KEYWORDS=[['GRAND TOTAL'],['TOTAL RM','TOTAL: RM'],['TOTAL AMOUNT'],['TOTAL DUE','AMOUNT DUE','BALANCE DUE','NETT TOTAL','NET TOTAL','TOTAL','AMOUNT']]
def to_amount(tok):
    tok=tok.strip().strip('.,;:|)')
    if ',' in tok and '.' not in tok and re.fullmatch(r'\d+,\d{2}', tok):
        tok=tok.replace(',','.')
    elif re.fullmatch(r'\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?', tok):
        tok=tok.replace(',','')
    return f"{Decimal(tok).quantize(Decimal('0.01')):.2f}"
def extract_total(text):
    lines=[ln.strip() for ln in text.splitlines() if ln.strip()]
    upper=[re.sub(r'\s+',' ',ln).upper() for ln in lines]
    def amounts(s):
        return [m.group(1) for m in _AMOUNT_RE.finditer(s)]
    def excluded(i):
        u=upper[i]; s=lines[i]
        if any(k in u for k in HARD):
            return True
        if any(k in u for k in CTX):
            return True
        if i>0:
            prev=upper[i-1]
            if any(k in prev for k in CTX) and any(k in prev for k in SOFT):
                return True
        if len(amounts(s))>=2 and ('RM' not in u and '$' not in u):
            return True
        if any(k in u for k in SOFT):
            if 'TOTAL' in u and len(amounts(s))==1:
                return False
            return True
        return False
    for group in KEYWORDS:
        for i in range(len(lines)-1,-1,-1):
            u=upper[i]
            if excluded(i):
                continue
            hit=False
            for kw in group:
                if kw in u:
                    if kw in {'TOTAL','AMOUNT'} and not re.search(r'\b'+re.escape(kw)+r'\b',u):
                        continue
                    hit=True;break
            if not hit:
                continue
            ts=amounts(lines[i])
            if ts:
                return to_amount(ts[-1]), lines[i]
            if i+1<len(lines) and not excluded(i+1):
                ts=amounts(lines[i+1])
                if ts:
                    return to_amount(ts[-1]), lines[i+1]
    return None,None
for (vi,psm),t in texts:
    amt,line=extract_total(t)
    if amt:
        print('variant',vi,'psm',psm,'->',amt,'from:',line)
